import{_ as t,c as o,o as r,ag as a}from"./chunks/framework.DuVOYUUM.js";const i="/pr-preview/pr-18/assets/ExampleCANBus.jlJEPThi.png",v=JSON.parse('{"title":"CAN Communication","description":"","frontmatter":{"order":2},"headers":[],"relativePath":"projects/igvc-2024/electrical/canbus.md","filePath":"projects/igvc-2024/electrical/canbus.md","lastUpdated":1790647345000}'),s={name:"projects/igvc-2024/electrical/canbus.md"};function n(l,e,d,c,h,u){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="can-communication" tabindex="-1">CAN Communication <a class="header-anchor" href="#can-communication" aria-label="Permalink to &quot;CAN Communication&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#overview">Overview</a></li><li><a href="#node-structure">Node Structure</a></li><li><a href="#node-network">Node Network</a></li><li><a href="#message-structure">Message Structure</a></li></ul></nav><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Within the electrical system of Horizon lies a CAN bus, used for communicating between devices. This style of communication protocal allows for the addition or removal of devices from the network while removing the need for any changes in the code of exisiting devices.</p><p>For a more detailed explaination on what a CAN bus is, refer to the <a href="https://en.wikipedia.org/wiki/CAN_bus?useskin=vector" target="_blank" rel="noreferrer">Wikipedia</a> page. For more information on the ODrive&#39;s use of CAN bus, refer to the <a href="https://docs.odriverobotics.com/v/latest/guides/can-guide.html#can-guide" target="_blank" rel="noreferrer">ODrive website</a></p><h2 id="node-structure" tabindex="-1">Node Structure <a class="header-anchor" href="#node-structure" aria-label="Permalink to &quot;Node Structure&quot;">​</a></h2><p>Each node on the CAN Bus requires 3 main things in order to function</p><ul><li>CPU or microprocessor <ul><li>The host processor decides what the recieved messages mean and what messages to transmit</li><li>Sensors, actuators, and control devices can be connected to the host processor</li></ul></li><li>CAN Controller <ul><li>Recieving: The CAN controller stores the recieved serial bits from the bus until the entire message is available, and then allows it to be fetched by the processor</li><li>Sending: Messages are recieved from the processor and then sent serially on the bus when it is free</li></ul></li><li>CAN Transciever <ul><li>Recieving: Converts the data stream from CAN bus levels to levels that the CAN controller can use</li><li>Sending: Converts the data stream from the CAN controller to CAN bus levels</li></ul></li></ul><h2 id="node-network" tabindex="-1">Node Network <a class="header-anchor" href="#node-network" aria-label="Permalink to &quot;Node Network&quot;">​</a></h2><img src="'+i+'" width="400" height="400" alt="Node Structure" style="horizontal-align:middle;"><h2 id="message-structure" tabindex="-1">Message Structure <a class="header-anchor" href="#message-structure" aria-label="Permalink to &quot;Message Structure&quot;">​</a></h2><p>The ODrive uses a CANSimple protocol built on CAN 2.0, where the command id is stored inside the region of the node id via bitshifting. The Data field works similarly to a normal CAN protocol. The most relevant commands the ODrive supports are as follows, a full listing can be found on the <a href="https://docs.odriverobotics.com/v/latest/manual/can-protocol.html#messages" target="_blank" rel="noreferrer">ODrive website</a>:</p><table tabindex="0"><thead><tr><th>Name</th><th>Command ID</th><th>Direction</th><th>Data</th></tr></thead><tbody><tr><td>Estop</td><td>0x02</td><td>Host -&gt; ODrive</td><td>N/A</td></tr><tr><td>Set_Axis_State</td><td>0x07</td><td>Host -&gt; ODrive</td><td><code>uint32 : Requested State</code></td></tr><tr><td>Set_Input_Pos</td><td>0x0C</td><td>Host -&gt; ODrive</td><td><code>float32 : Position(rev)</code> - <code>short : Velocity(0.001 rev/s)</code> - <code>short : Torque(0.001 Nm)</code></td></tr><tr><td>Set_Input_Vel</td><td>0x0D</td><td>Host -&gt; ODrive</td><td><code>float32 : Velocity(rev/s)</code> - <code>float32 : Torque(Nm)</code></td></tr></tbody></table>',13)]))}const f=t(s,[["render",n]]);export{v as __pageData,f as default};
